{
  "version": 3,
  "sources": ["../../functions/api/mcp/invoke.ts", "../../src/lib/security/hmacValidator.ts", "../../src/lib/omnibridge/registryEnv.ts", "../../src/lib/omnibridge/verifySignedIngress.ts", "../../src/core/types/index.ts", "../../src/core/orchestrator/ChronosLock.ts", "../../src/lib/omnibridge/replayStore.ts", "../../src/lib/omnibridge/eventEnvelope.ts", "../../src/lib/omnibridge/eventStore.ts", "../../src/lib/omnibridge/httpUtils.ts", "../../functions/api/omnibridge/ingest.ts", "../../src/lib/omnibridge/syncPacketVerifier.ts", "../../functions/api/omnibridge/sync.ts", "../pages-BvKuwJ/functionsWorker-0.3061519217554447.mjs/functionsRoutes-0.3083585460827023.mjs", "../pages-BvKuwJ/bundle-3ThcEj/middleware-loader.entry.ts", "../pages-BvKuwJ/bundle-3ThcEj/middleware-insertion-facade.js", "../../../../../../AppData/Roaming/npm/node_modules/wrangler/templates/pages-template-worker.ts", "../../../../../../AppData/Roaming/npm/node_modules/wrangler/node_modules/path-to-regexp/src/index.ts", "../../../../../../AppData/Roaming/npm/node_modules/wrangler/templates/middleware/middleware-ensure-req-body-drained.ts", "../../../../../../AppData/Roaming/npm/node_modules/wrangler/templates/middleware/middleware-miniflare3-json-error.ts", "../../../../../../AppData/Roaming/npm/node_modules/wrangler/templates/middleware/common.ts", "../../../../../../../AppData/Roaming/npm/node_modules/wrangler/templates/middleware/middleware-ensure-req-body-drained.ts", "../../../../../../../AppData/Roaming/npm/node_modules/wrangler/templates/middleware/middleware-miniflare3-json-error.ts", "../bundle-Mn4UEm/middleware-insertion-facade.js", "../../../../../../../AppData/Roaming/npm/node_modules/wrangler/templates/middleware/common.ts", "../bundle-Mn4UEm/middleware-loader.entry.ts"],
  "sourceRoot": "C:\\Users\\sinyo\\OMNILINK-APEX HUB\\APEX-OmniLink\\APEX-OmniHub\\APEX-OmniHub\\.wrangler\\tmp\\dev-IN01YT",
  "sourcesContent": ["/**\r\n * OmniPort Gateway \u2014 Cloudflare Pages Function\r\n * Route: /api/mcp/invoke\r\n * Version: 1.0.0\r\n *\r\n * Same-origin gateway for APEX Agent invocation.\r\n * - Requires POST + Authorization Bearer (Supabase user JWT)\r\n * - Inserts agent_run with status=queued\r\n * - Forwards to Supabase apex-agent with user JWT (not service-role)\r\n * - Polls agent_runs for terminal state\r\n * - Streams SSE: queued \u2192 running \u2192 completed/failed/timeout\r\n *\r\n * NON-NEGOTIABLES:\r\n * - Never uses service-role key for user-scoped reads\r\n * - Never leaks secrets or stack traces\r\n * - RLS preserved via user JWT forwarded to Supabase\r\n */\r\n\r\nexport const onRequestPost: PagesFunction = async (context) => {\r\n  const req = context.request;\r\n  const env = context.env as Record<string, string>;\r\n\r\n  // \u2500\u2500 CORS headers (same-origin gateway; browsers still send Origin on POST) \u2500\u2500\r\n  const origin = req.headers.get(\"Origin\") ?? \"\";\r\n  const corsHeaders: Record<string, string> = {\r\n    \"Access-Control-Allow-Origin\": origin,\r\n    \"Access-Control-Allow-Headers\": \"authorization, content-type, apikey, x-client-info\",\r\n    \"Access-Control-Allow-Methods\": \"POST, OPTIONS\",\r\n    \"Vary\": \"Origin\",\r\n  };\r\n\r\n  // \u2500\u2500 1. Auth \u2014 require Bearer token \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\r\n  const authHeader = req.headers.get(\"Authorization\");\r\n  if (!authHeader?.startsWith(\"Bearer \")) {\r\n    return jsonError(\"unauthorized\", 401, corsHeaders);\r\n  }\r\n  const userJwt = authHeader.slice(7).trim();\r\n  if (!userJwt) return jsonError(\"unauthorized\", 401, corsHeaders);\r\n\r\n  // \u2500\u2500 2. Content-Type \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\r\n  const ct = req.headers.get(\"Content-Type\") ?? \"\";\r\n  if (!ct.includes(\"application/json\")) {\r\n    return jsonError(\"unsupported_media_type\", 415, corsHeaders);\r\n  }\r\n\r\n  // \u2500\u2500 3. Parse + validate body \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\r\n  let body: Record<string, unknown>;\r\n  try {\r\n    body = await req.json();\r\n  } catch {\r\n    return jsonError(\"bad_request\", 400, corsHeaders);\r\n  }\r\n\r\n  const prompt = body.prompt;\r\n  if (typeof prompt !== \"string\" || prompt.length < 1 || prompt.length > 20_000) {\r\n    return jsonError(\"bad_request: prompt must be a string 1\u201320000 chars\", 400, corsHeaders);\r\n  }\r\n\r\n  // Validate optional fields\r\n  const context_ = body.context ?? {};\r\n  if (typeof context_ !== \"object\" || Array.isArray(context_)) {\r\n    return jsonError(\"bad_request: context must be a plain object\", 400, corsHeaders);\r\n  }\r\n\r\n  // Generate or validate traceId\r\n  let traceId: string;\r\n  if (typeof body.traceId === \"string\" && isValidUUID(body.traceId)) {\r\n    traceId = body.traceId;\r\n  } else {\r\n    traceId = crypto.randomUUID();\r\n  }\r\n\r\n  // Validate optional providerPreference (hint only, never authoritative)\r\n  const providerPreference = body.providerPreference;\r\n  if (\r\n    providerPreference !== undefined &&\r\n    providerPreference !== \"groq\" &&\r\n    providerPreference !== \"anthropic\"\r\n  ) {\r\n    // Silently ignore unsupported provider preference\r\n  }\r\n\r\n  // \u2500\u2500 4. Env validation \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\r\n  const supabaseUrl = env.SUPABASE_URL ?? env.VITE_SUPABASE_URL;\r\n  const supabaseAnonKey =\r\n    env.SUPABASE_PUBLISHABLE_KEY ??\r\n    env.VITE_SUPABASE_PUBLISHABLE_KEY ??\r\n    env.SUPABASE_ANON_KEY ??\r\n    env.VITE_SUPABASE_ANON_KEY ??\r\n    \"\";\r\n\r\n  if (!supabaseUrl) {\r\n    console.error(\"[omniport-gateway] SUPABASE_URL not configured\");\r\n    return jsonError(\"server_error\", 500, corsHeaders);\r\n  }\r\n\r\n  // \u2500\u2500 5. Insert agent_run as 'queued' before calling apex-agent \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\r\n  // Uses user JWT so RLS is enforced. Only inserts if row doesn't exist.\r\n  try {\r\n    await fetch(`${supabaseUrl}/rest/v1/agent_runs`, {\r\n      method: \"POST\",\r\n      headers: {\r\n        \"Authorization\": `Bearer ${userJwt}`,\r\n        \"apikey\": supabaseAnonKey,\r\n        \"Content-Type\": \"application/json\",\r\n        \"Prefer\": \"resolution=ignore-duplicates\",\r\n      },\r\n      body: JSON.stringify({\r\n        id: traceId,\r\n        status: \"queued\",\r\n        query: prompt,\r\n        created_at: new Date().toISOString(),\r\n      }),\r\n    });\r\n  } catch (err) {\r\n    console.error(\"[omniport-gateway] Failed to insert agent_run:\", err);\r\n    // Non-fatal \u2014 apex-agent may create the row or it may already exist\r\n  }\r\n\r\n  // \u2500\u2500 6. SSE response setup \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\r\n  const { readable, writable } = new TransformStream<Uint8Array, Uint8Array>();\r\n  const writer = writable.getWriter();\r\n  const enc = new TextEncoder();\r\n\r\n  const sseResponse = new Response(readable, {\r\n    status: 200,\r\n    headers: {\r\n      ...corsHeaders,\r\n      \"Content-Type\": \"text/event-stream\",\r\n      \"Cache-Control\": \"no-cache\",\r\n      \"Connection\": \"keep-alive\",\r\n    },\r\n  });\r\n\r\n  // \u2500\u2500 7. Async orchestration (fire-and-forget into background) \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\r\n  runGateway(\r\n    writer,\r\n    enc,\r\n    traceId,\r\n    prompt,\r\n    context_ as Record<string, unknown>,\r\n    userJwt,\r\n    supabaseUrl,\r\n    supabaseAnonKey,\r\n  ).catch((err) => {\r\n    console.error(\"[omniport-gateway] Unhandled gateway error:\", err);\r\n    writer.close().catch(() => {});\r\n  });\r\n\r\n  return sseResponse;\r\n};\r\n\r\n// \u2500\u2500 OPTIONS preflight \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\r\n\r\nexport const onRequestOptions: PagesFunction = async (context) => {\r\n  const origin = context.request.headers.get(\"Origin\") ?? \"\";\r\n  return new Response(null, {\r\n    status: 204,\r\n    headers: {\r\n      \"Access-Control-Allow-Origin\": origin,\r\n      \"Access-Control-Allow-Headers\": \"authorization, content-type, apikey, x-client-info\",\r\n      \"Access-Control-Allow-Methods\": \"POST, OPTIONS\",\r\n      \"Access-Control-Max-Age\": \"86400\",\r\n      \"Vary\": \"Origin\",\r\n    },\r\n  });\r\n};\r\n\r\n// \u2500\u2500 Gateway orchestration logic \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\r\n\r\nasync function runGateway(\r\n  writer: WritableStreamDefaultWriter<Uint8Array>,\r\n  enc: TextEncoder,\r\n  traceId: string,\r\n  prompt: string,\r\n  ctx: Record<string, unknown>,\r\n  userJwt: string,\r\n  supabaseUrl: string,\r\n  supabaseAnonKey: string,\r\n): Promise<void> {\r\n  const emit = async (event: string, data: Record<string, unknown>) => {\r\n    try {\r\n      await writer.write(enc.encode(`event: ${event}\\ndata: ${JSON.stringify(data)}\\n\\n`));\r\n    } catch {\r\n      // Stream may be closed\r\n    }\r\n  };\r\n\r\n  try {\r\n    // Emit queued\r\n    await emit(\"status\", { traceId, status: \"queued\" });\r\n\r\n    // Forward to apex-agent\r\n    const apexAgentUrl = `${supabaseUrl}/functions/v1/apex-agent`;\r\n    let agentResponse: Response;\r\n    try {\r\n      agentResponse = await fetch(apexAgentUrl, {\r\n        method: \"POST\",\r\n        headers: {\r\n          \"Authorization\": `Bearer ${userJwt}`,\r\n          \"apikey\": supabaseAnonKey,\r\n          \"Content-Type\": \"application/json\",\r\n        },\r\n        body: JSON.stringify({\r\n          query: prompt,\r\n          traceId,\r\n          context: ctx,\r\n        }),\r\n      });\r\n    } catch (err) {\r\n      console.error(\"[omniport-gateway] apex-agent fetch failed:\", err);\r\n      await emit(\"failed\", { traceId, status: \"failed\", error: \"upstream_unavailable\" });\r\n      await writer.close();\r\n      return;\r\n    }\r\n\r\n    if (agentResponse.status === 401) {\r\n      await emit(\"failed\", { traceId, status: \"failed\", error: \"unauthorized\" });\r\n      await writer.close();\r\n      return;\r\n    }\r\n\r\n    if (!agentResponse.ok) {\r\n      console.error(`[omniport-gateway] apex-agent returned ${agentResponse.status}`);\r\n      await emit(\"failed\", {\r\n        traceId,\r\n        status: \"failed\",\r\n        error: `upstream_error_${agentResponse.status}`,\r\n      });\r\n      await writer.close();\r\n      return;\r\n    }\r\n\r\n    // Parse agent response to get workflowId\r\n    let agentData: Record<string, unknown> = {};\r\n    try {\r\n      agentData = await agentResponse.json();\r\n    } catch {\r\n      // Non-fatal\r\n    }\r\n\r\n    const workflowId = typeof agentData.workflowId === \"string\" ? agentData.workflowId : undefined;\r\n\r\n    // Emit running\r\n    await emit(\"status\", { traceId, status: \"running\", workflowId });\r\n\r\n    // \u2500\u2500 Poll agent_runs for terminal state \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\r\n    const POLL_INTERVAL_MS = 750;\r\n    const TIMEOUT_MS = 90_000;\r\n    const startTime = Date.now();\r\n\r\n    while (Date.now() - startTime < TIMEOUT_MS) {\r\n      await sleep(POLL_INTERVAL_MS);\r\n\r\n      let rows: Array<Record<string, unknown>> = [];\r\n      try {\r\n        const pollRes = await fetch(\r\n          `${supabaseUrl}/rest/v1/agent_runs?id=eq.${encodeURIComponent(traceId)}&select=id,status,result,reply,error,workflow_id,completed_at`,\r\n          {\r\n            headers: {\r\n              \"Authorization\": `Bearer ${userJwt}`,\r\n              \"apikey\": supabaseAnonKey,\r\n              \"Accept\": \"application/json\",\r\n            },\r\n          },\r\n        );\r\n        if (pollRes.ok) {\r\n          rows = (await pollRes.json()) as Array<Record<string, unknown>>;\r\n        }\r\n      } catch (err) {\r\n        console.warn(\"[omniport-gateway] poll error:\", err);\r\n        // Continue polling \u2014 transient network error\r\n      }\r\n\r\n      const row = rows?.[0];\r\n      if (!row) continue;\r\n\r\n      const status = row.status as string | undefined;\r\n\r\n      if (status === \"completed\") {\r\n        const reply =\r\n          (row.reply as string | undefined) ??\r\n          (row.result as string | undefined) ??\r\n          \"\";\r\n        await emit(\"completed\", {\r\n          traceId,\r\n          status: \"completed\",\r\n          reply,\r\n          result: row.result ?? {},\r\n          workflowId: row.workflow_id ?? workflowId,\r\n        });\r\n        await writer.close();\r\n        return;\r\n      }\r\n\r\n      if (status === \"failed\") {\r\n        await emit(\"failed\", {\r\n          traceId,\r\n          status: \"failed\",\r\n          error: sanitizeError(row.error),\r\n          workflowId: row.workflow_id ?? workflowId,\r\n        });\r\n        await writer.close();\r\n        return;\r\n      }\r\n\r\n      // status is queued/running \u2014 keep polling\r\n    }\r\n\r\n    // Timeout\r\n    await emit(\"timeout\", {\r\n      traceId,\r\n      status: \"timeout\",\r\n      workflowId,\r\n    });\r\n    await writer.close();\r\n  } catch (err) {\r\n    console.error(\"[omniport-gateway] runGateway error:\", err);\r\n    try {\r\n      await emit(\"failed\", {\r\n        traceId,\r\n        status: \"failed\",\r\n        error: \"internal_gateway_error\",\r\n      });\r\n      await writer.close();\r\n    } catch {\r\n      // Already closed\r\n    }\r\n  }\r\n}\r\n\r\n// \u2500\u2500 Utilities \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\r\n\r\nfunction sleep(ms: number): Promise<void> {\r\n  return new Promise((resolve) => setTimeout(resolve, ms));\r\n}\r\n\r\nfunction isValidUUID(s: string): boolean {\r\n  return /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(s);\r\n}\r\n\r\nfunction sanitizeError(err: unknown): string {\r\n  if (typeof err === \"string\") {\r\n    // Remove any stack trace or secret patterns\r\n    return err.replace(/at\\s+\\w+.*$/gm, \"\").substring(0, 200).trim();\r\n  }\r\n  return \"agent_execution_failed\";\r\n}\r\n\r\nfunction jsonError(\r\n  message: string,\r\n  status: number,\r\n  corsHeaders: Record<string, string>,\r\n): Response {\r\n  return new Response(JSON.stringify({ error: message }), {\r\n    status,\r\n    headers: { ...corsHeaders, \"Content-Type\": \"application/json\" },\r\n  });\r\n}\r\n", "/**\r\n * HMAC-SHA256 Signature Validation Utility\r\n *\r\n * Edge-compatible (Web Crypto API only) HMAC generation and validation\r\n * with constant-time comparison to prevent timing attacks.\r\n *\r\n * @module lib/security/hmacValidator\r\n * @license Proprietary - APEX Business Systems Ltd.\r\n */\r\n\r\nconst encoder = new TextEncoder();\r\n\r\n/**\r\n * Import a string secret as a CryptoKey for HMAC-SHA256 operations.\r\n */\r\nasync function importKey(secret: string): Promise<CryptoKey> {\r\n  return crypto.subtle.importKey(\r\n    'raw',\r\n    encoder.encode(secret),\r\n    { name: 'HMAC', hash: 'SHA-256' },\r\n    false,\r\n    ['sign', 'verify'],\r\n  );\r\n}\r\n\r\n/**\r\n * Convert an ArrayBuffer to a hex-encoded string.\r\n */\r\nfunction bufferToHex(buffer: ArrayBuffer): string {\r\n  return Array.from(new Uint8Array(buffer))\r\n    .map((b) => b.toString(16).padStart(2, '0'))\r\n    .join('');\r\n}\r\n\r\n/**\r\n * Convert a hex-encoded string to a Uint8Array.\r\n */\r\nfunction hexToBuffer(hex: string): Uint8Array<ArrayBuffer> {\r\n  const bytes = new Uint8Array(hex.length / 2);\r\n  for (let i = 0; i < hex.length; i += 2) {\r\n    bytes[i / 2] = Number.parseInt(hex.substring(i, i + 2), 16);\r\n  }\r\n  return bytes;\r\n}\r\n\r\n/**\r\n * Constant-time string comparison to prevent timing attacks.\r\n *\r\n * Compares every character regardless of mismatch position, ensuring\r\n * the function execution time does not leak information about which\r\n * characters differ.\r\n */\r\nexport function timingSafeEqual(a: string, b: string): boolean {\r\n  if (a.length !== b.length) {\r\n    // Even on length mismatch we do work proportional to the longer string\r\n    // to avoid leaking length information via timing.\r\n    // However, we still return false since lengths differ.\r\n    let mismatch = 1;\r\n    const len = Math.max(a.length, b.length);\r\n    for (let i = 0; i < len; i++) {\r\n      const ac = a.codePointAt(i % a.length) ?? 0;\r\n      const bc = b.codePointAt(i % b.length) ?? 0;\r\n      mismatch |= ac ^ bc;\r\n    }\r\n    // Always returns false for length mismatch, but takes constant time\r\n    // relative to the longer input. mismatch is always >= 1 here.\r\n    return mismatch === 0;\r\n  }\r\n\r\n  let mismatch = 0;\r\n  for (let i = 0; i < a.length; i++) {\r\n    mismatch |= (a.codePointAt(i) ?? 0) ^ (b.codePointAt(i) ?? 0);\r\n  }\r\n  return mismatch === 0;\r\n}\r\n\r\n/**\r\n * Generate a hex-encoded HMAC-SHA256 signature for the given payload.\r\n *\r\n * @param payload - The raw string payload to sign\r\n * @param secret  - The signing secret\r\n * @returns Hex-encoded HMAC-SHA256 signature\r\n */\r\nexport async function generateHMAC(payload: string, secret: string): Promise<string> {\r\n  const key = await importKey(secret);\r\n  const signature = await crypto.subtle.sign('HMAC', key, encoder.encode(payload));\r\n  return bufferToHex(signature);\r\n}\r\n\r\n/**\r\n * Validate an HMAC-SHA256 signature against a payload using constant-time comparison.\r\n *\r\n * Uses `crypto.subtle.verify` which provides native constant-time comparison\r\n * for the cryptographic verification step.\r\n *\r\n * @param payload   - The raw string payload that was signed\r\n * @param signature - The hex-encoded signature to validate\r\n * @param secret    - The signing secret\r\n * @returns True if the signature is valid\r\n */\r\nexport async function validateHMAC(\r\n  payload: string,\r\n  signature: string,\r\n  secret: string,\r\n): Promise<boolean> {\r\n  try {\r\n    // Validate hex format\r\n    if (!/^[0-9a-f]{64}$/i.test(signature)) {\r\n      return false;\r\n    }\r\n\r\n    const key = await importKey(secret);\r\n    const signatureBytes = hexToBuffer(signature);\r\n\r\n    return crypto.subtle.verify('HMAC', key, signatureBytes, encoder.encode(payload));\r\n  } catch {\r\n    return false;\r\n  }\r\n}\r\n", "/**\r\n * Env-parameterized source registry resolution.\r\n *\r\n * The canonical sourceRegistry.ts reads process.env and caches. That works\r\n * on Node (tests) and Vercel Edge, but Cloudflare Pages Functions pass env\r\n * via context.env and don't populate process.env.\r\n *\r\n * This module provides env-aware versions used by the functions/ directory.\r\n * It intentionally does NOT cache across requests (each CF Pages Function\r\n * invocation may run on a different isolate / with different env snapshot).\r\n *\r\n * @module lib/omnibridge/registryEnv\r\n * @license Proprietary - APEX Business Systems Ltd.\r\n */\r\n\r\nimport type { M2MClientRecord, WebhookSourceResolution } from './sourceRegistry';\r\n\r\nexport interface RegistryEnv {\r\n  OMNIBRIDGE_M2M_CLIENTS?: string;\r\n  [key: string]: string | undefined;\r\n}\r\n\r\nconst parseErrors = new WeakMap<RegistryEnv, Error | null>();\r\n\r\nfunction validateWebhookShape(w: Record<string, unknown>): boolean {\r\n  if (typeof w.source_id !== 'string') return false;\r\n  if (typeof w.key_id !== 'string') return false;\r\n  if (typeof w.secret_env !== 'string') return false;\r\n  if (w.status !== 'active' && w.status !== 'inactive') return false;\r\n  if (w.profile !== undefined && w.profile !== 'hardened' && w.profile !== 'sync_packet') return false;\r\n  if (w.allowed_ips === undefined) return true;\r\n  if (!Array.isArray(w.allowed_ips)) return false;\r\n  for (const ip of w.allowed_ips) {\r\n    if (typeof ip !== 'string') return false;\r\n  }\r\n  return true;\r\n}\r\n\r\nfunction validateRecord(record: unknown): record is M2MClientRecord {\r\n  if (!record || typeof record !== 'object') return false;\r\n  const r = record as Record<string, unknown>;\r\n  if (typeof r.client_id !== 'string') return false;\r\n  if (typeof r.client_secret_hash !== 'string') return false;\r\n  if (!Array.isArray(r.scopes)) return false;\r\n  for (const s of r.scopes) {\r\n    if (typeof s !== 'string') return false;\r\n  }\r\n  if (typeof r.tenant_id !== 'string') return false;\r\n  if (r.webhook === undefined) return true;\r\n  const w = r.webhook as Record<string, unknown> | null;\r\n  if (!w || typeof w !== 'object') return false;\r\n  return validateWebhookShape(w);\r\n}\r\n\r\nfunction parseClients(env: RegistryEnv): M2MClientRecord[] | null {\r\n  const raw = env.OMNIBRIDGE_M2M_CLIENTS;\r\n  if (!raw) {\r\n    parseErrors.set(env, new Error('OMNIBRIDGE_M2M_CLIENTS is not configured'));\r\n    return null;\r\n  }\r\n  try {\r\n    const parsed = JSON.parse(raw) as unknown;\r\n    if (!Array.isArray(parsed)) {\r\n      parseErrors.set(env, new Error('OMNIBRIDGE_M2M_CLIENTS must be a JSON array'));\r\n      return null;\r\n    }\r\n    const out: M2MClientRecord[] = [];\r\n    for (const item of parsed) {\r\n      if (!validateRecord(item)) {\r\n        parseErrors.set(env, new Error('Malformed client record'));\r\n        return null;\r\n      }\r\n      out.push(item);\r\n    }\r\n    parseErrors.set(env, null);\r\n    return out;\r\n  } catch (e) {\r\n    parseErrors.set(env, new Error(`Failed to parse OMNIBRIDGE_M2M_CLIENTS: ${e instanceof Error ? e.message : String(e)}`));\r\n    return null;\r\n  }\r\n}\r\n\r\nexport function lastRegistryErrorFromEnv(env: RegistryEnv): Error | null {\r\n  return parseErrors.get(env) ?? null;\r\n}\r\n\r\nexport function resolveSyncPacketSourceFromEnv(\r\n  sourceId: string,\r\n  env: RegistryEnv,\r\n): WebhookSourceResolution | null {\r\n  const clients = parseClients(env);\r\n  if (!clients) return null;\r\n  for (const client of clients) {\r\n    if (!client.webhook) continue;\r\n    if (client.webhook.source_id !== sourceId) continue;\r\n    if (client.webhook.profile !== 'sync_packet') continue;\r\n    if (client.webhook.status !== 'active') return null;\r\n    const secret = env[client.webhook.secret_env];\r\n    if (!secret) {\r\n      console.error(`[omnibridge/registryEnv] Secret env ${client.webhook.secret_env} not set for ${sourceId}`);\r\n      return null;\r\n    }\r\n    return { client, webhook: client.webhook, secret };\r\n  }\r\n  return null;\r\n}\r\n\r\nexport function resolveHardenedSourceFromEnv(\r\n  sourceId: string,\r\n  keyId: string,\r\n  env: RegistryEnv,\r\n): WebhookSourceResolution | null {\r\n  const clients = parseClients(env);\r\n  if (!clients) return null;\r\n  for (const client of clients) {\r\n    if (!client.webhook) continue;\r\n    if (client.webhook.source_id !== sourceId) continue;\r\n    if (client.webhook.key_id !== keyId) continue;\r\n    // Default profile is 'hardened' when unspecified (back-compat).\r\n    if (client.webhook.profile && client.webhook.profile !== 'hardened') continue;\r\n    if (client.webhook.status !== 'active') return null;\r\n    const secret = env[client.webhook.secret_env];\r\n    if (!secret) {\r\n      console.error(`[omnibridge/registryEnv] Secret env ${client.webhook.secret_env} not set for ${sourceId}`);\r\n      return null;\r\n    }\r\n    return { client, webhook: client.webhook, secret };\r\n  }\r\n  return null;\r\n}\r\n", "/**\r\n * Hardened Request Verification Pipeline\r\n *\r\n * Implements the source-aware signed ingress logic for SBBL HQ and future\r\n * partners in a Vercel Edge compatible way.\r\n *\r\n * @module lib/omnibridge/verifySignedIngress\r\n * @license Proprietary - APEX Business Systems Ltd.\r\n */\r\n\r\n\r\n\r\n\r\nexport interface HardenedHeaders {\r\n  sourceId: string;\r\n  keyId: string;\r\n  timestamp: string;\r\n  traceId: string;\r\n  signature: string;\r\n}\r\n\r\n/**\r\n * Extracts hardened headers from a Request object.\r\n * Returns null if any header is completely missing.\r\n */\r\nexport function extractHardenedHeaders(request: Request): HardenedHeaders | null {\r\n  const sourceId = request.headers.get('X-Omni-Source');\r\n  const keyId = request.headers.get('X-Omni-Key-Id');\r\n  const timestamp = request.headers.get('X-Omni-Timestamp');\r\n  const traceId = request.headers.get('X-Omni-Trace-Id');\r\n  const signature = request.headers.get('X-Omni-Signature');\r\n\r\n  if (!sourceId || !keyId || !timestamp || !traceId || !signature) {\r\n    return null;\r\n  }\r\n\r\n  return { sourceId, keyId, timestamp, traceId, signature };\r\n}\r\n\r\n\r\n\r\n/**\r\n * Computes the canonical signature string for hardened mode.\r\n * HMAC must use raw request bytes to prevent bypasses via whitespace manipulation.\r\n */\r\nexport async function computeCanonicalString(\r\n  method: string,\r\n  path: string,\r\n  timestamp: string,\r\n  traceId: string,\r\n  sourceId: string,\r\n  bodyRaw: string\r\n): Promise<string> {\r\n  return `${method}\\n${path}\\n${timestamp}\\n${traceId}\\n${sourceId}\\n${bodyRaw}`;\r\n}\r\n\r\n/**\r\n * Validates the timestamp string.\r\n * Returns true if the timestamp is valid and within \u00B1300s of now.\r\n */\r\nexport function isTimestampValid(timestampStr: string, maxSkewSeconds = 300): boolean {\r\n  const ts = Number.parseInt(timestampStr, 10); // NOSONAR\r\n  if (Number.isNaN(ts) || ts <= 0) return false; // NOSONAR\r\n\r\n  const nowSeconds = Math.floor(Date.now() / 1000);\r\n  const diff = Math.abs(nowSeconds - ts);\r\n\r\n  return diff <= maxSkewSeconds;\r\n}\r\n\r\n/**\r\n * Validates IP address against a list of allowed CIDR/IP strings.\r\n * For now, this just supports direct string matching.\r\n */\r\nexport function isIpAllowed(ip: string, allowedIps: string[] | undefined): boolean {\r\n  if (!allowedIps || allowedIps.length === 0) return true; // Empty means allow all\r\n  return allowedIps.includes(ip);\r\n}\r\n\r\n/**\r\n * Extracts the real client IP from X-Forwarded-For.\r\n * On Cloudflare Pages / Vercel the platform appends the verified client IP\r\n * as the last entry, so we always trust XFF from the infrastructure layer.\r\n */\r\nexport function extractClientIp(request: Request): string {\r\n  const xff = request.headers.get('X-Forwarded-For');\r\n  if (xff) {\r\n    const ips = xff.split(',');\r\n    const last = ips.pop()?.trim();\r\n    if (last) return last;\r\n  }\r\n  return 'unknown';\r\n}\r\n", "/**\r\n * Core type definitions for APEX OmniHub Realtime System.\r\n *\r\n * Defines contracts for device classification, trust tiers,\r\n * tool manifests, and idempotency state management.\r\n *\r\n * @module core/types\r\n * @version 1.0.0\r\n * @date 2026-02-09\r\n */\r\n\r\n/* ------------------------------------------------------------------ */\r\n/*  Trust & Device Classification                                      */\r\n/* ------------------------------------------------------------------ */\r\n\r\n/**\r\n * Trust tiers aligned with ManLane risk classification.\r\n * Maps to AegisKernel permission enforcement.\r\n */\r\nexport enum TrustTier {\r\n  /** Full system access \u2014 admin-only. */\r\n  GOD_MODE = 'GOD_MODE',\r\n  /** Operational access \u2014 deploy, file system, invoicing. */\r\n  OPERATOR = 'OPERATOR',\r\n  /** Peripheral access \u2014 audio, logging, read insight. */\r\n  PERIPHERAL = 'PERIPHERAL',\r\n  /** Minimal read-only access \u2014 unauthenticated or unknown. */\r\n  PUBLIC = 'PUBLIC',\r\n}\r\n\r\n/** Capabilities a device may possess. */\r\nexport type DeviceCapability =\r\n  | 'all'\r\n  | 'audio_in'\r\n  | 'audio_out'\r\n  | 'log_insight'\r\n  | 'file_system'\r\n  | 'deploy_service'\r\n  | 'create_invoice'\r\n  | 'read_only';\r\n\r\n/** Authenticated device profile attached to every connection. */\r\nexport interface DeviceProfile {\r\n  readonly deviceId: string;\r\n  readonly trustTier: TrustTier;\r\n  readonly capabilities: ReadonlyArray<DeviceCapability>;\r\n  readonly connectionId: string;\r\n  readonly authenticatedAt: string;\r\n}\r\n\r\n/* ------------------------------------------------------------------ */\r\n/*  Tool Manifest                                                      */\r\n/* ------------------------------------------------------------------ */\r\n\r\n/** OpenAI function-tool JSON Schema shape. */\r\nexport interface ToolFunctionSchema {\r\n  readonly type: 'function';\r\n  readonly function: {\r\n    readonly name: string;\r\n    readonly description: string;\r\n    readonly parameters: Record<string, unknown>;\r\n  };\r\n}\r\n\r\n/** Filtered manifest response returned to devices. */\r\nexport interface ToolManifestResponse {\r\n  readonly tools: ReadonlyArray<ToolFunctionSchema>;\r\n  readonly meta: {\r\n    readonly device_id: string;\r\n    readonly trust_tier: TrustTier;\r\n    readonly count: number;\r\n    readonly generated_at: string;\r\n  };\r\n}\r\n\r\n/* ------------------------------------------------------------------ */\r\n/*  Idempotency / Chronos                                              */\r\n/* ------------------------------------------------------------------ */\r\n\r\n/** Idempotency lock states. */\r\nexport enum IdempotencyState {\r\n  PENDING = 'PENDING',\r\n  COMPLETED = 'COMPLETED',\r\n}\r\n\r\n/** A single idempotency record managed by ChronosLock. */\r\nexport interface IdempotencyRecord {\r\n  readonly key: string;\r\n  readonly state: IdempotencyState;\r\n  readonly createdAt: string;\r\n  readonly completedAt?: string;\r\n  readonly result?: unknown;\r\n}\r\n\r\n/* ------------------------------------------------------------------ */\r\n/*  Realtime Events                                                    */\r\n/* ------------------------------------------------------------------ */\r\n\r\n/** Parsed tool call extracted from OpenAI Realtime events. */\r\nexport interface ParsedToolCall {\r\n  readonly toolName: string;\r\n  readonly args: Record<string, unknown>;\r\n  readonly callId: string;\r\n  readonly idempotencyKey: string;\r\n}\r\n\r\n/** Safe error payload sent to clients (no stack traces). */\r\nexport interface SafeErrorPayload {\r\n  readonly error: string;\r\n  readonly correlationId: string;\r\n  readonly timestamp: string;\r\n}\r\n\r\n/* ------------------------------------------------------------------ */\r\n/*  Orchestrator Tool Execution                                        */\r\n/* ------------------------------------------------------------------ */\r\n\r\n/** Input contract for ApexOrchestrator.executeTool(). */\r\nexport interface ToolExecutionInput {\r\n  readonly toolName: string;\r\n  readonly args: Record<string, unknown>;\r\n  readonly device: DeviceProfile;\r\n  readonly idempotencyKey: string;\r\n  readonly callId: string;\r\n}\r\n\r\n/** Output contract from ApexOrchestrator.executeTool(). */\r\nexport interface ToolExecutionResult {\r\n  readonly success: boolean;\r\n  readonly callId: string;\r\n  readonly output: unknown;\r\n  readonly error?: string;\r\n}\r\n", "/**\r\n * ChronosLock \u2014 Durable Idempotency State Machine.\r\n *\r\n * Manages PENDING \u2192 COMPLETED transitions for tool-call idempotency keys.\r\n * Provides deterministic duplicate detection and safe replay via a pluggable\r\n * DurableIdempotencyStore.\r\n *\r\n * Two adapters are provided:\r\n *  - InMemoryIdempotencyStore  \u2192 single-process / test use\r\n *  - SupabaseIdempotencyStore  \u2192 production distributed deployment\r\n *\r\n * @module core/orchestrator/ChronosLock\r\n * @version 2.0.0\r\n * @date 2026-05-27\r\n */\r\n\r\nimport {\r\n  type IdempotencyRecord,\r\n  IdempotencyState,\r\n} from '../types/index';\r\n\r\n/* ------------------------------------------------------------------ */\r\n/*  Durable Store Interface                                             */\r\n/* ------------------------------------------------------------------ */\r\n\r\nexport interface DurableIdempotencyStore {\r\n  /** Return the record if it exists, otherwise null. */\r\n  get(key: string, tenantId?: string): Promise<IdempotencyRecord | null>;\r\n\r\n  /**\r\n   * Atomically insert a PENDING record.\r\n   * @returns true if inserted (new), false if already existed (duplicate).\r\n   */\r\n  insertPending(key: string, meta: { toolName?: string; deviceId?: string; tenantId?: string }): Promise<boolean>;\r\n\r\n  /** Transition PENDING \u2192 COMPLETED and store the result. */\r\n  complete(key: string, result: unknown, tenantId?: string): Promise<boolean>;\r\n\r\n  /** Remove a PENDING record (rollback). */\r\n  deletePending(key: string, tenantId?: string): Promise<boolean>;\r\n\r\n  /** TEST ONLY \u2014 clear all records. */\r\n  _reset?(): void;\r\n}\r\n\r\n/* ------------------------------------------------------------------ */\r\n/*  In-Memory Adapter (single-process / tests)                         */\r\n/* ------------------------------------------------------------------ */\r\n\r\nclass InMemoryIdempotencyStore implements DurableIdempotencyStore {\r\n  private readonly store = new Map<string, IdempotencyRecord>();\r\n\r\n  async get(key: string): Promise<IdempotencyRecord | null> {\r\n    return this.store.get(key) ?? null;\r\n  }\r\n\r\n  async insertPending(key: string): Promise<boolean> {\r\n    if (this.store.has(key)) return false;\r\n    this.store.set(key, {\r\n      key,\r\n      state: IdempotencyState.PENDING,\r\n      createdAt: new Date().toISOString(),\r\n    });\r\n    return true;\r\n  }\r\n\r\n  async complete(key: string, result: unknown): Promise<boolean> {\r\n    const record = this.store.get(key);\r\n    if (!record || record.state !== IdempotencyState.PENDING) return false;\r\n    this.store.set(key, {\r\n      ...record,\r\n      state: IdempotencyState.COMPLETED,\r\n      completedAt: new Date().toISOString(),\r\n      result,\r\n    });\r\n    return true;\r\n  }\r\n\r\n  async deletePending(key: string): Promise<boolean> {\r\n    return this.deletePendingSync(key);\r\n  }\r\n\r\n  getSync(key: string): IdempotencyRecord | undefined {\r\n    return this.store.get(key);\r\n  }\r\n\r\n  setSync(key: string, record: IdempotencyRecord): void {\r\n    this.store.set(key, record);\r\n  }\r\n\r\n  deletePendingSync(key: string): boolean {\r\n    const record = this.store.get(key);\r\n    if (record?.state !== IdempotencyState.PENDING) return false;\r\n    this.store.delete(key);\r\n    return true;\r\n  }\r\n\r\n  _reset(): void {\r\n    this.store.clear();\r\n  }\r\n}\r\n\r\n/* ------------------------------------------------------------------ */\r\n/*  Active store (swappable at runtime)                                 */\r\n/* ------------------------------------------------------------------ */\r\n\r\nlet _store: DurableIdempotencyStore = new InMemoryIdempotencyStore();\r\n\r\n/**\r\n * Inject a durable store (e.g. Supabase adapter) at startup.\r\n */\r\nexport function setIdempotencyStore(store: DurableIdempotencyStore): void {\r\n  _store = store;\r\n}\r\n\r\n/* ------------------------------------------------------------------ */\r\n/*  Public API \u2014 backwards-compatible synchronous wrappers             */\r\n/*  (maintained for callers that have not yet migrated to async)        */\r\n/* ------------------------------------------------------------------ */\r\n\r\n/**\r\n * Acquire an idempotency lock.\r\n *\r\n * @returns { isNew, record } \u2014 isNew=false means duplicate (already in-flight or complete).\r\n * @deprecated Prefer acquireAsync for new code.\r\n */\r\nexport function acquire(\r\n  key: string,\r\n): { isNew: boolean; record: IdempotencyRecord } {\r\n  // Synchronous shim over the in-memory store for backward compat.\r\n  // The in-memory store ops are synchronous by nature; Promise.resolve wraps are transparent.\r\n  const inMem = _store as InMemoryIdempotencyStore;\r\n  const existing = inMem.getSync(key);\r\n  if (existing) return { isNew: false, record: existing };\r\n\r\n  const record: IdempotencyRecord = {\r\n    key,\r\n    state: IdempotencyState.PENDING,\r\n    createdAt: new Date().toISOString(),\r\n  };\r\n  inMem.setSync(key, record);\r\n  return { isNew: true, record };\r\n}\r\n\r\n/**\r\n * Commit an idempotency key to COMPLETED with a result.\r\n * @deprecated Prefer commitAsync for new code.\r\n */\r\nexport function commit(key: string, result?: unknown): boolean {\r\n  const inMem = _store as InMemoryIdempotencyStore;\r\n  const record = inMem.getSync(key);\r\n  if (!record || record.state !== IdempotencyState.PENDING) return false;\r\n  inMem.setSync(key, {\r\n    ...record,\r\n    state: IdempotencyState.COMPLETED,\r\n    completedAt: new Date().toISOString(),\r\n    result,\r\n  });\r\n  return true;\r\n}\r\n\r\n/**\r\n * Roll back (delete) a PENDING idempotency key.\r\n * @deprecated Prefer rollbackAsync for new code.\r\n */\r\nexport function rollback(key: string): boolean {\r\n  const inMem = _store as InMemoryIdempotencyStore;\r\n  const record = inMem.getSync(key);\r\n  if (!record || record.state !== IdempotencyState.PENDING) return false;\r\n  return inMem.deletePendingSync(key);\r\n}\r\n\r\n/**\r\n * Look up an idempotency record.\r\n * @deprecated Prefer lookupAsync for new code.\r\n */\r\nexport function lookup(key: string): IdempotencyRecord | undefined {\r\n  const inMem = _store as InMemoryIdempotencyStore;\r\n  return inMem.getSync(key);\r\n}\r\n\r\n/* ------------------------------------------------------------------ */\r\n/*  Async API (durable-store compatible)                               */\r\n/* ------------------------------------------------------------------ */\r\n\r\nexport async function acquireAsync(\r\n  key: string,\r\n  meta: { toolName?: string; deviceId?: string; tenantId?: string } = {},\r\n): Promise<{ isNew: boolean; record: IdempotencyRecord | null }> {\r\n  const isNew = await _store.insertPending(key, meta);\r\n  if (!isNew) {\r\n    const record = await _store.get(key, meta.tenantId);\r\n    return { isNew: false, record };\r\n  }\r\n  return {\r\n    isNew: true,\r\n    record: {\r\n      key,\r\n      state: IdempotencyState.PENDING,\r\n      createdAt: new Date().toISOString(),\r\n    },\r\n  };\r\n}\r\n\r\nexport async function commitAsync(\r\n  key: string,\r\n  result: unknown,\r\n  tenantId?: string,\r\n): Promise<boolean> {\r\n  return _store.complete(key, result, tenantId);\r\n}\r\n\r\nexport async function rollbackAsync(\r\n  key: string,\r\n  tenantId?: string,\r\n): Promise<boolean> {\r\n  return _store.deletePending(key, tenantId);\r\n}\r\n\r\nexport async function lookupAsync(\r\n  key: string,\r\n  tenantId?: string,\r\n): Promise<IdempotencyRecord | null> {\r\n  return _store.get(key, tenantId);\r\n}\r\n\r\n/* ------------------------------------------------------------------ */\r\n/*  Test utilities                                                      */\r\n/* ------------------------------------------------------------------ */\r\n\r\nexport function _resetForTesting(): void {\r\n  if (_store._reset) {\r\n    _store._reset();\r\n  }\r\n}\r\n", "/**\r\n * Idempotency & Replay Store for OmniBridge\r\n *\r\n * Provides best-effort deduplication within a single Vercel Edge isolate.\r\n * Keys on source_id + trace_id for hardened mode.\r\n *\r\n * @module lib/omnibridge/replayStore\r\n * @license Proprietary - APEX Business Systems Ltd.\r\n */\r\n\r\nimport { acquireAsync } from '../../core/orchestrator/ChronosLock';\r\n\r\nexport interface ReplayStore {\r\n  /**\r\n   * Check if an idempotency key or composite replay key has already been processed.\r\n   * Returns true if the key is a duplicate (already processed).\r\n   */\r\n  isDuplicate(key: string): Promise<boolean>;\r\n}\r\n\r\nclass DurableReplayStore implements ReplayStore {\r\n  public async isDuplicate(key: string): Promise<boolean> {\r\n    try {\r\n      const { isNew } = await acquireAsync(key, { toolName: 'omnibridge_ingest' });\r\n      return !isNew;\r\n    } catch (e) {\r\n      // In case of store failure, fail-closed is safer for idempotency, \r\n      // but we could also fail-open if availability > exactly-once.\r\n      // Default to fail-closed (act as duplicate).\r\n      console.error('ReplayStore failure:', e);\r\n      return true;\r\n    }\r\n  }\r\n}\r\n\r\nexport const replayStore = new DurableReplayStore();\r\n\r\n/**\r\n * Generates a hardened mode replay key.\r\n */\r\nexport function getHardenedReplayKey(sourceId: string, traceId: string): string {\r\n  return `omnibridge:replay:${sourceId}:${traceId}`;\r\n}\r\n\r\n/**\r\n * Generates a legacy mode idempotency key.\r\n */\r\nexport function getLegacyIdempotencyKey(key: string): string {\r\n  return `omnibridge:idempotency:${key}`;\r\n}\r\n\r\n/**\r\n * Clears the in-memory store. Useful for testing.\r\n */\r\nexport function clearReplayStore(): void {\r\n  import('../../core/orchestrator/ChronosLock').then(({ _resetForTesting }) => {\r\n    _resetForTesting();\r\n  });\r\n}\r\n", "/**\r\n * Event Envelope Normalization for OmniBridge\r\n *\r\n * Runtime-safe helper to normalize incoming payload shapes into a predictable\r\n * structured event. This preserves inbound tracing, idempotency, and tenant identifiers,\r\n * ensuring failure on malformed input.\r\n *\r\n * Designed to replace or standardize the legacy direct parsing from ingest.ts.\r\n *\r\n * @module lib/omnibridge/eventEnvelope\r\n * @license Proprietary - APEX Business Systems Ltd.\r\n */\r\n\r\nexport type DeliveryStatus = 'accepted' | 'normalized' | 'persisted' | 'dispatched' | 'failed_retryable' | 'failed_terminal';\r\n\r\nexport interface EventEnvelope {\r\n  event_id: string;\r\n  event_type: string;\r\n  tenant_id: string;\r\n  timestamp: string;\r\n  payload: Record<string, unknown>;\r\n  idempotency_key: string | null;\r\n  trace_id: string | null;\r\n  source_id: string | null;\r\n  received_at: string;\r\n  delivery_status: DeliveryStatus;\r\n}\r\n\r\n/**\r\n * Normalizes a hardened payload into the standard EventEnvelope.\r\n */\r\nexport function normalizeHardenedEvent(\r\n  rawPayload: Record<string, unknown>,\r\n  tenantId: string,\r\n  timestamp: string,\r\n  traceId: string,\r\n  sourceId: string,\r\n  eventId: string,\r\n  idempotencyKey?: string\r\n): EventEnvelope {\r\n  // We trust the tenant_id from the registry match, rather than the payload body for hardened routes\r\n  // But we still require the payload to at least have an event_type.\r\n  if (typeof rawPayload.event_type !== 'string' || !rawPayload.event_type) {\r\n    throw new Error('FAIL_CLOSED: Missing event_type in hardened payload');\r\n  }\r\n\r\n  return {\r\n    event_id: eventId,\r\n    event_type: rawPayload.event_type,\r\n    tenant_id: tenantId, // Strict match from registry overrides payload tenant\r\n    timestamp,\r\n    payload: rawPayload.payload && typeof rawPayload.payload === 'object' && !Array.isArray(rawPayload.payload)\r\n             ? (rawPayload.payload as Record<string, unknown>)\r\n             : rawPayload, // Default to the whole body if it doesn't wrap inside \"payload\"\r\n    idempotency_key: idempotencyKey ?? null,\r\n    trace_id: traceId,\r\n    source_id: sourceId,\r\n    received_at: new Date().toISOString(),\r\n    delivery_status: 'normalized'\r\n  };\r\n}\r\n\r\n/**\r\n * Normalizes a legacy payload into the standard EventEnvelope.\r\n */\r\nexport function normalizeLegacyEvent(\r\n  rawPayload: Record<string, unknown>,\r\n  eventId: string\r\n): EventEnvelope {\r\n  if (typeof rawPayload.event_type !== 'string' || !rawPayload.event_type) {\r\n    throw new Error('FAIL_CLOSED: Missing event_type in legacy payload');\r\n  }\r\n  if (typeof rawPayload.tenant_id !== 'string' || !rawPayload.tenant_id) {\r\n    throw new Error('FAIL_CLOSED: Missing tenant_id in legacy payload');\r\n  }\r\n  if (typeof rawPayload.timestamp !== 'string' || !rawPayload.timestamp) {\r\n    throw new Error('FAIL_CLOSED: Missing timestamp in legacy payload');\r\n  }\r\n  if (!rawPayload.payload || typeof rawPayload.payload !== 'object' || Array.isArray(rawPayload.payload)) {\r\n    throw new Error('FAIL_CLOSED: Missing or invalid payload object in legacy payload');\r\n  }\r\n\r\n  // Validate timestamp is a parseable date\r\n  if (Number.isNaN(Date.parse(rawPayload.timestamp))) {\r\n    throw new Error('FAIL_CLOSED: Invalid timestamp format'); // NOSONAR\r\n  }\r\n\r\n  let idempotencyKey: string | null = null;\r\n  if (rawPayload.idempotency_key !== undefined) {\r\n    if (typeof rawPayload.idempotency_key !== 'string') {\r\n      throw new Error('FAIL_CLOSED: idempotency_key must be a string'); // NOSONAR\r\n    }\r\n    idempotencyKey = rawPayload.idempotency_key;\r\n  }\r\n\r\n  return {\r\n    event_id: eventId,\r\n    event_type: rawPayload.event_type,\r\n    tenant_id: rawPayload.tenant_id,\r\n    timestamp: rawPayload.timestamp,\r\n    payload: rawPayload.payload as Record<string, unknown>,\r\n    idempotency_key: idempotencyKey,\r\n    trace_id: null,\r\n    source_id: null,\r\n    received_at: new Date().toISOString(),\r\n    delivery_status: 'normalized'\r\n  };\r\n}\r\n", "/**\r\n * OmniBridge Event Store \u2014 durable event persistence.\r\n *\r\n * Called by both the hardened and sync_packet ingress profiles after signature\r\n * verification succeeds.\r\n *\r\n * Design:\r\n *   - Writes every verified event to omnibridge_events (idempotent on\r\n *     (source_id, event_id)).\r\n *   - Edge-safe: uses fetch (no SDK). The service role key is provided via env\r\n *     and is never logged. Callers run on Cloudflare Pages Functions and POST\r\n *     to Supabase PostgREST directly.\r\n *\r\n * Fail-closed: a persistence failure surfaces to the caller so the partner\r\n * receives a 5xx and retries.\r\n *\r\n * Dispatch infrastructure: recordDispatchFailure() and updateDispatchState()\r\n * are implemented and available but are NOT wired in production ingress paths.\r\n * They must be called explicitly by an orchestrator dispatch layer when that\r\n * integration is activated.\r\n *\r\n * @module lib/omnibridge/eventStore\r\n * @license Proprietary - APEX Business Systems Ltd.\r\n */\r\n\r\nexport type PersistProfile = 'hardened' | 'sync_packet' | 'legacy';\r\n\r\n/**\r\n * Platform-agnostic env bag. CF Pages Functions pass it via context.env.\r\n * Tests and Node code can pass process.env directly (string-indexable).\r\n */\r\nexport interface EventStoreEnv {\r\n  SUPABASE_URL?: string;\r\n  VITE_SUPABASE_URL?: string;\r\n  SUPABASE_SERVICE_ROLE_KEY?: string;\r\n}\r\n\r\nexport interface PersistEventInput {\r\n  event_id: string;\r\n  source_id: string;\r\n  tenant_id: string;\r\n  profile: PersistProfile;\r\n  event_type: string;\r\n  trace_id?: string | null;\r\n  idempotency_key?: string | null;\r\n  payload: Record<string, unknown>;\r\n  raw_headers?: Record<string, string> | null;\r\n  signature_verified: boolean;\r\n}\r\n\r\nexport interface PersistResult {\r\n  ok: true;\r\n  event_uuid: string;\r\n  duplicate: boolean;\r\n}\r\n\r\nexport interface PersistFailure {\r\n  ok: false;\r\n  reason: 'config_missing' | 'upstream_error' | 'conflict';\r\n  detail?: string;\r\n}\r\n\r\nexport type PersistOutcome = PersistResult | PersistFailure;\r\n\r\nconst HARDCODED_TIMEOUT_MS = 3_000;\r\n\r\n/**\r\n * Resolve Supabase config from an explicit env bag. On CF Pages Functions\r\n * callers pass context.env. On Node (tests) the caller may pass process.env.\r\n * Returns null when required values aren't set \u2014 caller decides how to fail.\r\n */\r\nfunction readSupabaseConfig(env: EventStoreEnv | undefined): { url: string; serviceKey: string } | null {\r\n  const source = env ?? (typeof process !== 'undefined' ? process.env : {});\r\n  const url = source.SUPABASE_URL ?? source.VITE_SUPABASE_URL;\r\n  const serviceKey = source.SUPABASE_SERVICE_ROLE_KEY;\r\n  if (url && serviceKey) return { url, serviceKey };\r\n  return null;\r\n}\r\n\r\n/**\r\n * Insert a verified event. Uses ON CONFLICT DO NOTHING semantics via\r\n * PostgREST `Prefer: resolution=ignore-duplicates` so replays (same\r\n * source_id + event_id) return the existing row as duplicate=true.\r\n */\r\nexport async function persistEvent(\r\n  input: PersistEventInput,\r\n  env?: EventStoreEnv,\r\n): Promise<PersistOutcome> {\r\n  const cfg = readSupabaseConfig(env);\r\n  if (!cfg) {\r\n    return { ok: false, reason: 'config_missing', detail: 'SUPABASE_URL or SUPABASE_SERVICE_ROLE_KEY not set' };\r\n  }\r\n\r\n  const body = [{\r\n    event_id: input.event_id,\r\n    source_id: input.source_id,\r\n    tenant_id: input.tenant_id,\r\n    profile: input.profile,\r\n    event_type: input.event_type,\r\n    trace_id: input.trace_id ?? null,\r\n    idempotency_key: input.idempotency_key ?? null,\r\n    payload: input.payload,\r\n    raw_headers: input.raw_headers ?? null,\r\n    signature_verified: input.signature_verified,\r\n  }];\r\n\r\n  const controller = new AbortController();\r\n  const timer = setTimeout(() => controller.abort(), HARDCODED_TIMEOUT_MS);\r\n\r\n  try {\r\n    const res = await fetch(`${cfg.url}/rest/v1/omnibridge_events?on_conflict=source_id,event_id`, {\r\n      method: 'POST',\r\n      headers: {\r\n        'apikey': cfg.serviceKey,\r\n        'Authorization': `Bearer ${cfg.serviceKey}`,\r\n        'Content-Type': 'application/json',\r\n        'Prefer': 'return=representation,resolution=ignore-duplicates',\r\n      },\r\n      body: JSON.stringify(body),\r\n      signal: controller.signal,\r\n    });\r\n\r\n    if (!res.ok) {\r\n      const text = await res.text().catch(() => '');\r\n      return { ok: false, reason: 'upstream_error', detail: `${res.status} ${text.slice(0, 200)}` };\r\n    }\r\n\r\n    const rows = await res.json() as Array<{ id: string }>;\r\n    if (!Array.isArray(rows) || rows.length === 0) {\r\n      // resolution=ignore-duplicates returns [] when the row already existed.\r\n      // We still need the id of the existing row for dispatch linking.\r\n      const lookup = await fetch(\r\n        `${cfg.url}/rest/v1/omnibridge_events?source_id=eq.${encodeURIComponent(input.source_id)}&event_id=eq.${encodeURIComponent(input.event_id)}&select=id`,\r\n        { headers: { 'apikey': cfg.serviceKey, 'Authorization': `Bearer ${cfg.serviceKey}` } },\r\n      );\r\n      if (!lookup.ok) {\r\n        return { ok: false, reason: 'upstream_error', detail: `duplicate lookup failed: ${lookup.status}` };\r\n      }\r\n      const existing = await lookup.json() as Array<{ id: string }>;\r\n      if (!existing[0]) {\r\n        return { ok: false, reason: 'conflict', detail: 'duplicate with no persisted row' };\r\n      }\r\n      return { ok: true, event_uuid: existing[0].id, duplicate: true };\r\n    }\r\n\r\n    return { ok: true, event_uuid: rows[0].id, duplicate: false };\r\n  } catch (e) {\r\n    return { ok: false, reason: 'upstream_error', detail: e instanceof Error ? e.message : String(e) };\r\n  } finally {\r\n    clearTimeout(timer);\r\n  }\r\n}\r\n\r\n/**\r\n * Record a dispatch failure to the DLQ. Exponential-backoff next_retry_at\r\n * computed from retry_count: 30s, 2m, 10m, 1h, 6h, 24h (capped).\r\n */\r\nconst BACKOFF_MINUTES = [0.5, 2, 10, 60, 360, 1440];\r\n\r\nexport async function recordDispatchFailure(\r\n  input: {\r\n    event_uuid: string;\r\n    target_url: string;\r\n    error_message: string;\r\n    http_status?: number;\r\n    retry_count?: number;\r\n  },\r\n  env?: EventStoreEnv,\r\n): Promise<void> {\r\n  const cfg = readSupabaseConfig(env);\r\n  if (!cfg) return;\r\n\r\n  const retryCount = input.retry_count ?? 0;\r\n  const backoffIdx = Math.min(retryCount, BACKOFF_MINUTES.length - 1);\r\n  const nextRetryAt = new Date(Date.now() + BACKOFF_MINUTES[backoffIdx] * 60_000).toISOString();\r\n\r\n  try {\r\n    await fetch(`${cfg.url}/rest/v1/omnibridge_events_dlq`, {\r\n      method: 'POST',\r\n      headers: {\r\n        'apikey': cfg.serviceKey,\r\n        'Authorization': `Bearer ${cfg.serviceKey}`,\r\n        'Content-Type': 'application/json',\r\n      },\r\n      body: JSON.stringify([{\r\n        event_uuid: input.event_uuid,\r\n        target_url: input.target_url,\r\n        error_message: input.error_message.slice(0, 2000),\r\n        http_status: input.http_status ?? null,\r\n        retry_count: retryCount,\r\n        next_retry_at: nextRetryAt,\r\n        last_attempted_at: new Date().toISOString(),\r\n      }]),\r\n    });\r\n  } catch {\r\n    // Swallow \u2014 DLQ is best-effort, primary event row is already durable.\r\n  }\r\n}\r\n\r\n/**\r\n * Mark an event row as dispatched/acknowledged. Best-effort.\r\n */\r\nexport async function updateDispatchState(\r\n  input: {\r\n    event_uuid: string;\r\n    state: 'accepted' | 'normalized' | 'persisted' | 'dispatching' | 'dispatched' | 'acknowledged' | 'dlq' | 'failed_retryable' | 'failed_terminal';\r\n    error?: string;\r\n    attempts_delta?: number;\r\n    dispatch_target?: string;\r\n  },\r\n  env?: EventStoreEnv,\r\n): Promise<void> {\r\n  const cfg = readSupabaseConfig(env);\r\n  if (!cfg) return;\r\n\r\n  const nowIso = new Date().toISOString();\r\n  const patch: Record<string, unknown> = { dispatch_state: input.state };\r\n  if (input.state === 'dispatched') patch.dispatched_at = nowIso;\r\n  if (input.state === 'acknowledged') patch.acknowledged_at = nowIso;\r\n  if (input.error) patch.dispatch_last_error = input.error.slice(0, 2000);\r\n  if (input.dispatch_target) patch.dispatch_target = input.dispatch_target;\r\n\r\n  try {\r\n    await fetch(`${cfg.url}/rest/v1/omnibridge_events?id=eq.${encodeURIComponent(input.event_uuid)}`, {\r\n      method: 'PATCH',\r\n      headers: {\r\n        'apikey': cfg.serviceKey,\r\n        'Authorization': `Bearer ${cfg.serviceKey}`,\r\n        'Content-Type': 'application/json',\r\n      },\r\n      body: JSON.stringify(patch),\r\n    });\r\n  } catch {\r\n    // Swallow \u2014 downstream correctness does not depend on state log.\r\n  }\r\n}\r\n", "/**\r\n * Shared HTTP utilities for OmniBridge CF Pages Functions.\r\n * Eliminates duplication between functions/api/omnibridge/sync.ts and ingest.ts.\r\n *\r\n * @module lib/omnibridge/httpUtils\r\n * @license Proprietary - APEX Business Systems Ltd.\r\n */\r\n\r\nfunction redactUnsafeResponseValue(value: unknown): unknown {\r\n  if (value instanceof Error) {\r\n    return { name: value.name || 'Error' };\r\n  }\r\n  if (Array.isArray(value)) {\r\n    return value.map(redactUnsafeResponseValue);\r\n  }\r\n  if (value !== null && typeof value === 'object') {\r\n    const redacted: Record<string, unknown> = {};\r\n    for (const [key, childValue] of Object.entries(value as Record<string, unknown>)) {\r\n      if (/^(stack|cause)$/i.test(key)) continue;\r\n      redacted[key] = redactUnsafeResponseValue(childValue);\r\n    }\r\n    return redacted;\r\n  }\r\n  return value;\r\n}\r\n\r\nexport function jsonResponse(status: number, body: Record<string, unknown>): Response {\r\n  return new Response(JSON.stringify(redactUnsafeResponseValue(body)), {\r\n    status,\r\n    headers: { 'Content-Type': 'application/json' },\r\n  });\r\n}\r\n\r\nexport function makeLogger(module: string) {\r\n  return (deny: boolean, reason: string, meta: Record<string, unknown>): void => {\r\n    const line = `[${module}] ${deny ? 'DENY' : 'ACCEPT'}: ${reason} | ${JSON.stringify(meta)}`;\r\n    if (deny) console.error(line); else console.warn(line);\r\n  };\r\n}\r\n\r\nexport function sanitize(obj: Record<string, unknown>): Record<string, unknown> {\r\n  const out: Record<string, unknown> = {};\r\n  for (const [k, v] of Object.entries(obj)) {\r\n    if (k.startsWith('__')) continue;\r\n    if (typeof v === 'string' && /<script/i.test(v)) continue;\r\n    if (v !== null && typeof v === 'object' && !Array.isArray(v)) {\r\n      out[k] = sanitize(v as Record<string, unknown>);\r\n    } else if (Array.isArray(v)) {\r\n      out[k] = v\r\n        .map((item) => {\r\n          if (item !== null && typeof item === 'object' && !Array.isArray(item)) {\r\n            return sanitize(item as Record<string, unknown>);\r\n          }\r\n          if (typeof item === 'string' && /<script/i.test(item)) return undefined;\r\n          return item;\r\n        })\r\n        .filter((item) => item !== undefined);\r\n    } else {\r\n      out[k] = v;\r\n    }\r\n  }\r\n  return out;\r\n}\r\n", "/**\r\n * CF Pages Function: POST /api/omnibridge/ingest\r\n *\r\n * Hardened 5-header HMAC ingress (existing contract, now on CF Pages).\r\n * Mirrors the prior api/omnibridge/ingest.ts but uses the CF Pages\r\n * onRequestPost signature + context.env binding. The underlying\r\n * verification + canonical-string logic is unchanged.\r\n *\r\n * @module functions/api/omnibridge/ingest\r\n * @license Proprietary - APEX Business Systems Ltd.\r\n */\r\n\r\nimport { validateHMAC } from '../../../src/lib/security/hmacValidator';\r\n\r\n// Inline secure ID generator \u2014 avoids pulling in src/lib/security.ts which\r\n// imports the Vite-only @/guardian/loops alias that CF Pages Functions\r\n// bundler (esbuild) cannot resolve. crypto.randomUUID is available in\r\n// the Cloudflare Workers / Pages Functions runtime.\r\nfunction generateSecureId(): string {\r\n  return crypto.randomUUID();\r\n}\r\nimport {\r\n  resolveHardenedSourceFromEnv,\r\n  lastRegistryErrorFromEnv,\r\n} from '../../../src/lib/omnibridge/registryEnv';\r\nimport {\r\n  extractHardenedHeaders,\r\n  computeCanonicalString,\r\n  isTimestampValid,\r\n  isIpAllowed,\r\n  extractClientIp,\r\n} from '../../../src/lib/omnibridge/verifySignedIngress';\r\nimport {\r\n  replayStore,\r\n  getHardenedReplayKey,\r\n  getLegacyIdempotencyKey,\r\n} from '../../../src/lib/omnibridge/replayStore';\r\nimport {\r\n  normalizeHardenedEvent,\r\n  normalizeLegacyEvent,\r\n  type EventEnvelope,\r\n} from '../../../src/lib/omnibridge/eventEnvelope';\r\nimport { persistEvent, type EventStoreEnv } from '../../../src/lib/omnibridge/eventStore';\r\nimport { jsonResponse, makeLogger, sanitize } from '../../../src/lib/omnibridge/httpUtils';\r\n\r\ninterface Env extends EventStoreEnv {\r\n  OMNIBRIDGE_M2M_CLIENTS?: string;\r\n  OMNIBRIDGE_ALLOW_LEGACY_SINGLE_SECRET?: string;\r\n  OMNIBRIDGE_WEBHOOK_SECRET?: string;\r\n  [key: string]: string | undefined;\r\n}\r\n\r\ntype HardenedHeaders = NonNullable<ReturnType<typeof extractHardenedHeaders>>;\r\n\r\nconst logEvent = makeLogger('omnibridge/ingest');\r\n\r\nfunction toErrorMessage(e: unknown): string {\r\n  return e instanceof Error ? e.message : String(e);\r\n}\r\n\r\nfunction isTenantMismatch(parsedBody: Record<string, unknown>, expectedTenantId: string): boolean {\r\n  return !!parsedBody.tenant_id && parsedBody.tenant_id !== expectedTenantId;\r\n}\r\n\r\nasync function handleHardenedIngress(\r\n  request: Request,\r\n  rawBody: string,\r\n  headers: HardenedHeaders,\r\n  env: Env,\r\n): Promise<Response> {\r\n  const { sourceId, keyId, timestamp, traceId, signature } = headers;\r\n  const meta = { mode: 'hardened' as const, source_id: sourceId, trace_id: traceId };\r\n\r\n  if (!isTimestampValid(timestamp, 300)) {\r\n    logEvent(true, 'invalid_timestamp', meta);\r\n    return jsonResponse(400, { error: 'invalid_timestamp' });\r\n  }\r\n\r\n  const replayKey = getHardenedReplayKey(sourceId, traceId);\r\n  if (await replayStore.isDuplicate(replayKey)) {\r\n    logEvent(true, 'replay_detected', meta);\r\n    return jsonResponse(409, { error: 'replay_detected' });\r\n  }\r\n\r\n  const resolution = resolveHardenedSourceFromEnv(sourceId, keyId, env);\r\n  if (lastRegistryErrorFromEnv(env)) {\r\n    logEvent(true, 'server_config_error', meta);\r\n    return jsonResponse(500, { error: 'server_config_error' });\r\n  }\r\n  if (!resolution) {\r\n    logEvent(true, 'invalid_key_id', meta);\r\n    return jsonResponse(401, { error: 'invalid_key_id' });\r\n  }\r\n\r\n  const clientIp = extractClientIp(request);\r\n  if (!isIpAllowed(clientIp, resolution.webhook.allowed_ips)) {\r\n    logEvent(true, 'ip_not_allowed', { ...meta, client_ip: clientIp });\r\n    return jsonResponse(403, { error: 'ip_not_allowed' });\r\n  }\r\n\r\n  const path = new URL(request.url).pathname;\r\n  const canonical = await computeCanonicalString(request.method, path, timestamp, traceId, sourceId, rawBody);\r\n  if (!(await validateHMAC(canonical, signature, resolution.secret))) {\r\n    logEvent(true, 'invalid_signature', meta);\r\n    return jsonResponse(401, { error: 'invalid_signature' });\r\n  }\r\n\r\n  let parsedBody: Record<string, unknown>;\r\n  try {\r\n    parsedBody = JSON.parse(rawBody) as Record<string, unknown>;\r\n  } catch {\r\n    logEvent(true, 'invalid_json', meta);\r\n    return jsonResponse(400, { error: 'invalid_json' });\r\n  }\r\n\r\n  let eventEnvelope: EventEnvelope;\r\n  try {\r\n    const idempotencyKey = typeof parsedBody.idempotency_key === 'string'\r\n      ? parsedBody.idempotency_key\r\n      : undefined;\r\n    eventEnvelope = normalizeHardenedEvent(\r\n      parsedBody,\r\n      resolution.client.tenant_id,\r\n      timestamp,\r\n      traceId,\r\n      sourceId,\r\n      generateSecureId(),\r\n      idempotencyKey,\r\n    );\r\n  } catch (e) {\r\n    logEvent(true, 'invalid_payload', { ...meta, error: toErrorMessage(e) });\r\n    return jsonResponse(400, { error: 'invalid_payload' });\r\n  }\r\n\r\n  if (isTenantMismatch(parsedBody, resolution.client.tenant_id)) {\r\n    logEvent(true, 'tenant_mismatch', meta);\r\n    return jsonResponse(403, { error: 'tenant_mismatch' });\r\n  }\r\n\r\n  eventEnvelope.payload = sanitize(eventEnvelope.payload);\r\n\r\n  const persist = await persistEvent({\r\n    event_id: eventEnvelope.event_id,\r\n    source_id: sourceId,\r\n    tenant_id: resolution.client.tenant_id,\r\n    profile: 'hardened',\r\n    event_type: eventEnvelope.event_type,\r\n    trace_id: eventEnvelope.trace_id,\r\n    idempotency_key: eventEnvelope.idempotency_key,\r\n    payload: eventEnvelope.payload,\r\n    raw_headers: {\r\n      'x-omni-source': sourceId,\r\n      'x-omni-key-id': keyId,\r\n      'x-omni-timestamp': timestamp,\r\n      'x-omni-trace-id': traceId,\r\n    },\r\n    signature_verified: true,\r\n  }, env);\r\n\r\n  if (!persist.ok) {\r\n    if (persist.reason === 'config_missing') {\r\n      logEvent(false, 'event_received_no_store', meta);\r\n      return jsonResponse(200, { received: true, event_id: eventEnvelope.event_id, stored: false });\r\n    }\r\n    logEvent(true, `persist_failed:${persist.reason}`, { ...meta, detail: persist.detail });\r\n    return jsonResponse(502, { error: 'persist_failed', reason: persist.reason });\r\n  }\r\n\r\n  logEvent(false, persist.duplicate ? 'idempotent_accept' : 'event_persisted', { ...meta, event_uuid: persist.event_uuid });\r\n  return jsonResponse(200, {\r\n    received: true,\r\n    event_id: eventEnvelope.event_id,\r\n    event_uuid: persist.event_uuid,\r\n    duplicate: persist.duplicate,\r\n  });\r\n}\r\n\r\nasync function handleLegacyIngress(request: Request, rawBody: string, env: Env): Promise<Response> {\r\n  const allowLegacy = env.OMNIBRIDGE_ALLOW_LEGACY_SINGLE_SECRET === 'true';\r\n  if (!allowLegacy) {\r\n    const hasAnyHardened = request.headers.has('X-Omni-Source') || request.headers.has('X-Omni-Key-Id');\r\n    if (hasAnyHardened) {\r\n      return jsonResponse(401, { error: 'missing_signature' });\r\n    }\r\n    return jsonResponse(403, { error: 'legacy_mode_disabled' });\r\n  }\r\n\r\n  const legacySignature = request.headers.get('X-OmniBridge-Signature');\r\n  if (!legacySignature) return jsonResponse(401, { error: 'missing_signature' });\r\n\r\n  const webhookSecret = env.OMNIBRIDGE_WEBHOOK_SECRET;\r\n  if (!webhookSecret) return jsonResponse(500, { error: 'server_config_error' });\r\n\r\n  if (!(await validateHMAC(rawBody, legacySignature, webhookSecret))) {\r\n    return jsonResponse(401, { error: 'invalid_signature' });\r\n  }\r\n\r\n  let parsedBody: Record<string, unknown>;\r\n  try {\r\n    parsedBody = JSON.parse(rawBody) as Record<string, unknown>;\r\n  } catch {\r\n    return jsonResponse(400, { error: 'invalid_json' });\r\n  }\r\n\r\n  let envelope: EventEnvelope;\r\n  try {\r\n    envelope = normalizeLegacyEvent(parsedBody, generateSecureId());\r\n  } catch (e) {\r\n    console.warn('[omnibridge/ingest] normalizeLegacyEvent failed', e);\r\n    return jsonResponse(400, { error: 'invalid_payload' });\r\n  }\r\n\r\n  if (envelope.idempotency_key) {\r\n    const key = getLegacyIdempotencyKey(envelope.idempotency_key);\r\n    if (await replayStore.isDuplicate(key)) {\r\n      return jsonResponse(200, { received: true, event_id: envelope.event_id, duplicate: true });\r\n    }\r\n  }\r\n\r\n  envelope.payload = sanitize(envelope.payload);\r\n  return jsonResponse(200, { received: true, event_id: envelope.event_id });\r\n}\r\n\r\ntype OnRequestPost = (context: { request: Request; env: Env }) => Promise<Response>;\r\n\r\nexport const onRequestPost: OnRequestPost = async ({ request, env }) => {\r\n  const rawBody = await request.text();\r\n  const hardenedHeaders = extractHardenedHeaders(request);\r\n\r\n  if (hardenedHeaders) {\r\n    return handleHardenedIngress(request, rawBody, hardenedHeaders, env);\r\n  }\r\n  return handleLegacyIngress(request, rawBody, env);\r\n};\r\n\r\ntype OnRequest = (context: { request: Request; env: Env }) => Promise<Response>;\r\nexport const onRequest: OnRequest = async ({ request, env }) => {\r\n  if (request.method !== 'POST') {\r\n    return jsonResponse(405, { error: 'method_not_allowed' });\r\n  }\r\n  return onRequestPost({ request, env });\r\n};\r\n", "/**\r\n * SBBL-HQ Native Sync Packet Verifier\r\n *\r\n * Accepts SBBL-HQ's native outbound format produced by\r\n * sbbl-hq/src/lib/sync-packets.ts::signSyncPacket:\r\n *\r\n *   Body:  { packet: SyncPacket, signature: base64url(HMAC-SHA256(secret, JSON.stringify(packet))) }\r\n *\r\n * Edge-compatible (Web Crypto API only). Constant-time verification via\r\n * crypto.subtle.verify.\r\n *\r\n * @module lib/omnibridge/syncPacketVerifier\r\n * @license Proprietary - APEX Business Systems Ltd.\r\n */\r\n\r\nconst encoder = new TextEncoder();\r\n\r\nexport interface SyncPacket {\r\n  packet_id: string;\r\n  trace_id: string;\r\n  event_type: string;\r\n  entity_type: string;\r\n  entity_id: string | null;\r\n  league_id: string | null;\r\n  payload: Record<string, unknown>;\r\n  emitted_at: string;\r\n}\r\n\r\nexport interface SyncPacketEnvelope {\r\n  packet: SyncPacket;\r\n  signature: string;\r\n}\r\n\r\nexport interface VerifyOptions {\r\n  maxSkewSeconds?: number;\r\n}\r\n\r\nexport interface VerifyResult {\r\n  valid: boolean;\r\n  reason?: 'malformed' | 'bad_signature' | 'expired' | 'invalid_timestamp';\r\n}\r\n\r\nfunction base64UrlToBytes(value: string): Uint8Array<ArrayBuffer> | null {\r\n  // NOSONAR javascript:S5547 \u2014 atob() is the correct Web Crypto-compatible\r\n  // primitive for base64url decoding in Cloudflare Pages Functions runtime.\r\n  // Node's Buffer API is not available; atob/btoa are the canonical choice.\r\n  if (!/^[A-Za-z0-9_-]+$/.test(value)) return null;\r\n  const padLen = (4 - (value.length % 4)) % 4;\r\n  const normalized = value.replaceAll('-', '+').replaceAll('_', '/') + '='.repeat(padLen);\r\n  try {\r\n    const binary = atob(normalized); // NOSONAR \u2014 see justification above\r\n    const out = new Uint8Array(binary.length);\r\n    for (let i = 0; i < binary.length; i++) out[i] = binary.codePointAt(i) ?? 0;\r\n    return out;\r\n  } catch {\r\n    return null;\r\n  }\r\n}\r\n\r\nconst SYNC_PACKET_STRING_FIELDS = ['packet_id', 'trace_id', 'event_type', 'entity_type', 'emitted_at'] as const;\r\n\r\nfunction isRecord(value: unknown): value is Record<string, unknown> {\r\n  return Boolean(value) && typeof value === 'object' && !Array.isArray(value);\r\n}\r\n\r\nfunction hasRequiredPacketStrings(packet: Record<string, unknown>): boolean {\r\n  return SYNC_PACKET_STRING_FIELDS.every((field) => typeof packet[field] === 'string' && packet[field].length > 0);\r\n}\r\n\r\nexport function isSyncPacketEnvelope(value: unknown): value is SyncPacketEnvelope {\r\n  if (!isRecord(value) || typeof value.signature !== 'string' || value.signature.length === 0) return false;\r\n  if (!isRecord(value.packet) || !hasRequiredPacketStrings(value.packet)) return false;\r\n  if (!isRecord(value.packet.payload)) return false;\r\n  return (value.packet.entity_id === null || typeof value.packet.entity_id === 'string')\r\n    && (value.packet.league_id === null || typeof value.packet.league_id === 'string');\r\n}\r\n\r\n/**\r\n * Validate that emitted_at is an ISO string and within maxSkewSeconds of now.\r\n */\r\nexport function isEmittedAtValid(emittedAt: string, maxSkewSeconds: number): boolean {\r\n  const ms = Date.parse(emittedAt);\r\n  if (Number.isNaN(ms)) return false;\r\n  const nowMs = Date.now();\r\n  return Math.abs(nowMs - ms) <= maxSkewSeconds * 1000;\r\n}\r\n\r\n/**\r\n * Verify the SBBL-HQ native sync packet envelope.\r\n *\r\n * Fails closed on any shape, signature, or timestamp violation.\r\n */\r\nexport async function verifySyncPacket(\r\n  envelope: SyncPacketEnvelope,\r\n  secret: string,\r\n  options: VerifyOptions = {},\r\n): Promise<VerifyResult> {\r\n  const maxSkewSeconds = options.maxSkewSeconds ?? 300;\r\n\r\n  if (!isSyncPacketEnvelope(envelope)) {\r\n    return { valid: false, reason: 'malformed' };\r\n  }\r\n\r\n  if (!isEmittedAtValid(envelope.packet.emitted_at, maxSkewSeconds)) {\r\n    return { valid: false, reason: 'expired' };\r\n  }\r\n\r\n  const sigBytes = base64UrlToBytes(envelope.signature);\r\n  if (!sigBytes) {\r\n    return { valid: false, reason: 'bad_signature' };\r\n  }\r\n\r\n  con